-- NEW create+price+receipt tests only. Existing core/basics suites are not rerun.
SET LOCAL TimeZone='UTC';
CREATE SCHEMA price_create_test;
GRANT USAGE ON SCHEMA price_create_test TO anon,authenticated,service_role;
CREATE FUNCTION price_create_test.ok(v boolean,label text) RETURNS void LANGUAGE plpgsql AS $t$
BEGIN
 IF v IS DISTINCT FROM true THEN RAISE EXCEPTION 'PRICE_CREATE_ASSERT_FAILED: %',label; END IF;
 RAISE NOTICE 'PRICE_CREATE_PASS: %',label;
END $t$;
CREATE FUNCTION price_create_test.rows() RETURNS jsonb LANGUAGE sql SECURITY DEFINER
SET search_path=pg_catalog,public,pg_temp SET timezone='UTC' AS $t$
 SELECT jsonb_build_object('listings',(SELECT jsonb_agg(to_jsonb(l) ORDER BY id) FROM public.listings l),
 'receipts',(SELECT jsonb_agg(to_jsonb(r) ORDER BY actor_user_id,request_key) FROM public.listing_creation_receipts_v1 r));
$t$;
CREATE FUNCTION price_create_test.error(statement text,code text,message text,label text)
RETURNS void LANGUAGE plpgsql AS $t$
DECLARE got_code text; got_message text; before_rows jsonb;
BEGIN
 before_rows:=price_create_test.rows();
 BEGIN EXECUTE statement;
 EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS got_code=RETURNED_SQLSTATE,got_message=MESSAGE_TEXT;
 END;
 PERFORM price_create_test.ok(got_code IS NOT DISTINCT FROM code
  AND (message IS NULL OR got_message IS NOT DISTINCT FROM message)
  AND before_rows IS NOT DISTINCT FROM price_create_test.rows(),label);
END $t$;
CREATE TABLE price_create_test.results(name text PRIMARY KEY,value jsonb NOT NULL);
GRANT ALL ON price_create_test.results TO authenticated;
CREATE FUNCTION price_create_test.key(i integer) RETURNS uuid LANGUAGE sql IMMUTABLE AS $t$
 SELECT ('10000000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid;
$t$;
CREATE FUNCTION price_create_test.input() RETURNS jsonb LANGUAGE sql IMMUTABLE AS $t$ SELECT '{"basics":{"title":"Test title","description":"Test description","condition":"used"},"price":{"kind":"fixed","amount":"123.40","currency":"EUR"},"category_path":["vehicles","trucks_commercial","trucks"],"location":{"country":"Estonia","city":"Paide","latitude":"0","longitude":"0"},"attributes":{"manufacturer":"","part_number":"","oem_number":"","vehicle_brand":"","vehicle_model":"","vehicle_year":"","engine":""},"details":{"power":"90KW","model":"Gaz 53"},"language":"et"}'::jsonb; $t$;
