CREATE FUNCTION price_create_test.late_error() RETURNS trigger LANGUAGE plpgsql AS $t$
BEGIN
 IF EXISTS(SELECT 1 FROM public.listings WHERE id=NEW.listing_id AND title='Late failure') THEN
  RAISE EXCEPTION 'synthetic_after_receipt_failure' USING ERRCODE='P0001';
 END IF;
 RETURN NEW;
END $t$;
CREATE TRIGGER synthetic_late_create AFTER INSERT ON public.listing_creation_receipts_v1
 FOR EACH ROW EXECUTE FUNCTION price_create_test.late_error();
RESET ROLE; SET LOCAL request.jwt.claim.sub='11111111-1111-4111-8111-111111111111'; SET LOCAL request.jwt.claim.role='authenticated'; SET LOCAL ROLE authenticated;
